// public/js/wb-wand.js — transisi tongkat peri (home -> download)
// Pakai: WBWand.play(url)  atau  WBWand.play(() => {...})
window.WBWand = (function () {
  // gambar tongkat ditanam langsung (tidak butuh file/path terpisah)
  const EMBEDDED = 'data:image/png;base64,';
  // titik bintang & ujung gagang di gambar tongkat (relatif 0..1)
  const STAR = { x: 0.53, y: 0.16 };
  const HANDLE = { x: 0.04, y: 0.975 };
  const COLORS = ['#FFC400', '#FFD84D', '#FFE066', '#FFFFFF', '#FFFFFF', '#FFF7C2', '#FFB800'];
  let running = false;

  // hapus latar putih (kalau gambar belum transparan) lalu crop ke batas tongkat
  function prepare(im) {
    const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;
    const x = c.getContext('2d'); x.drawImage(im, 0, 0);
    let d; try { d = x.getImageData(0, 0, c.width, c.height); } catch (e) { return c; }
    const a = d.data; let hasAlpha = false;
    for (let i = 3; i < a.length; i += 4) { if (a[i] < 250) { hasAlpha = true; break; } }
    if (!hasAlpha) for (let i = 0; i < a.length; i += 4) {
      const m = Math.min(a[i], a[i + 1], a[i + 2]); a[i + 3] = Math.max(0, Math.min(255, (255 - m - 6) * 4));
    }
    let x0 = c.width, y0 = c.height, x1 = 0, y1 = 0;
    for (let y = 0; y < c.height; y++) for (let xx = 0; xx < c.width; xx++) {
      if (a[(y * c.width + xx) * 4 + 3] > 40) { if (xx < x0) x0 = xx; if (xx > x1) x1 = xx; if (y < y0) y0 = y; if (y > y1) y1 = y; }
    }
    if (x1 <= x0 || y1 <= y0) return c;
    x.putImageData(d, 0, 0);
    const o = document.createElement('canvas'); o.width = x1 - x0 + 1; o.height = y1 - y0 + 1;
    o.getContext('2d').drawImage(c, x0, y0, o.width, o.height, 0, 0, o.width, o.height);
    return o;
  }

  const ease = (t) => t < .5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;

  function sparkle(ctx, x, y, r, rot) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(rot);
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const rad = i % 2 === 0 ? r : r * 0.28, ang = (Math.PI / 4) * i;
      ctx.lineTo(Math.cos(ang) * rad, Math.sin(ang) * rad);
    }
    ctx.closePath(); ctx.fill(); ctx.restore();
  }

  function play(target) {
    if (running) return; running = true;
    const go = () => { typeof target === 'function' ? target() : (location.href = target); };
    const reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
    try { sessionStorage.setItem('wb_arrive_dl', '1'); } catch (e) {}
    if (reduce) { setTimeout(go, 150); return; }

    const cv = document.createElement('canvas');
    cv.setAttribute('aria-hidden', 'true');
    cv.style.cssText = 'position:fixed;inset:0;width:100%;height:100%;z-index:99999;pointer-events:all;';
    document.body.appendChild(cv);
    const ctx = cv.getContext('2d');
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let W = innerWidth, H = innerHeight;
    cv.width = W * dpr; cv.height = H * dpr; ctx.scale(dpr, dpr);

    // gambar utama: images/whimsybooth/wb-wand.png (diset lewat window.WB_WAND_SRC); cadangan: gambar tertanam
    const MAIN = window.WB_WAND_SRC || '/images/whimsybooth/wb-wand.png';
    let img = new Image(), spr = null, usedFallback = false;
    let ready = false;
    img.src = MAIN;

    const K = Math.max(0.9, Math.min(Math.min(W, H) / 430, 2.2));
    const INTRO = 1100, DUR = 3000, FLASH_AT = 0.80; // INTRO: tongkat muncul tegak dulu; DUR: fase spiral
    const cx = W / 2, cy = H / 2;
    const Rmax = Math.min(W, H) * 0.30;
    const wandH = Math.min(H * 0.42, W * 0.62, 380);
    const turns = 2.4, phi0 = -Math.PI / 2;
    const trail = [], parts = [];
    let lastP = 0, t0 = null, prev = null, done = false, last = 0;

    // posisi bintang saat tongkat berdiri tegak di awal
    const S0 = { x: cx, y: cy - wandH * 0.30 };
    const blend = (q) => ease(Math.min(Math.max(q, 0) / 0.14, 1));
    const lerp = (a, b, t) => a + (b - a) * t;
    function posB(q) { const B = pos(q), b = blend(q); return { x: lerp(S0.x, B.x, b), y: lerp(S0.y, B.y, b) }; }

    function pos(p) {
      const e = ease(p);
      const R = Rmax * Math.pow(1 - e, 0.85) + 4;
      const phi = phi0 + Math.PI * 2 * turns * e;
      return { x: cx + Math.cos(phi) * R, y: cy + Math.sin(phi) * R * 0.82 };
    }

    function frame(ts) {
      if (done) return;
      if (t0 === null) { t0 = ts; last = ts; }
      const el = ts - t0, p = Math.min(Math.max(el - INTRO, 0) / DUR, 1), spiral = el >= INTRO, dt = Math.min((ts - last) / 1000, 0.05); last = ts;
      ctx.clearRect(0, 0, W, H);

      // latar lembut selaras warna home
      const bgA = Math.min(el / 380, 1);
      const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(W, H) * 0.75);
      g.addColorStop(0, 'rgba(255,243,250,' + (0.96 * bgA) + ')');
      g.addColorStop(0.6, 'rgba(255,214,236,' + (0.95 * bgA) + ')');
      g.addColorStop(1, 'rgba(232,212,255,' + (0.97 * bgA) + ')');
      ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);

      const P = posB(p), pe = posB(Math.min(p + 0.004, 1));
      let vx = pe.x - P.x, vy = pe.y - P.y;
      if (!vx && !vy) { vx = prev ? P.x - prev.x : 1; vy = prev ? P.y - prev.y : 0; }
      prev = P;

      if (spiral && p < FLASH_AT + 0.05) {
        // isi titik di antara frame supaya spiral mulus walau frame rate turun
        for (let q = lastP + 0.003; q < p; q += 0.003) { const Q = posB(q); trail.push({ x: Q.x, y: Q.y, t: el - (p - q) * DUR }); }
        trail.push({ x: P.x, y: P.y, t: el }); lastP = p;
        const n = 22 + Math.floor(Math.random() * 14);
        for (let i = 0; i < n; i++) {
          const a = Math.random() * Math.PI * 2, sp = (20 + Math.random() * 120) * K;
          parts.push({ x: P.x + (Math.random() - .5) * 14, y: P.y + (Math.random() - .5) * 14,
            vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 10, life: 0, max: 0.8 + Math.random() * 1.3,
            r: (1.5 + Math.random() * 5) * K, star: Math.random() < 0.55, rot: Math.random() * 3,
            c: COLORS[(Math.random() * COLORS.length) | 0] });
        }
      }

      // fase intro: tongkat tegak, kilau kecil di bintang
      if (!spiral && el > 350 && Math.random() < 0.5) {
        const a = Math.random() * Math.PI * 2, d = (12 + Math.random() * 40) * K;
        parts.push({ x: S0.x + Math.cos(a) * d, y: S0.y + Math.sin(a) * d, vx: Math.cos(a) * 10 * K, vy: -8 * K, life: 0,
          max: 0.7 + Math.random() * 0.6, r: (1.5 + Math.random() * 3) * K, star: true, rot: Math.random() * 3,
          c: COLORS[(Math.random() * COLORS.length) | 0] });
      }

      // sprinkle menyebar mengikuti bentuk spiral (di sepanjang jejak)
      if (spiral && p < FLASH_AT + 0.03 && trail.length > 3) {
        for (let i = 0; i < 26; i++) {
          const tp = trail[Math.max(0, trail.length - 1 - Math.floor(Math.random() * Math.min(trail.length, 110)))];
          const a = Math.random() * Math.PI * 2, sp = (10 + Math.random() * 40) * K, j = (6 + Math.random() * 26) * K;
          parts.push({ x: tp.x + Math.cos(a) * j, y: tp.y + Math.sin(a) * j, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 8,
            life: 0, max: 1.0 + Math.random() * 1.6, r: (1.3 + Math.random() * 4.2) * K, star: Math.random() < 0.6, rot: Math.random() * 3,
            c: COLORS[(Math.random() * COLORS.length) | 0] });
        }
      }

      // jejak cahaya spiral
      const life = 2100;
      while (trail.length && el - trail[0].t > life) trail.shift();
      for (let i = 1; i < trail.length; i++) {
        const a = trail[i - 1], b = trail[i], age = (el - b.t) / life, k = 1 - age;
        ctx.strokeStyle = 'rgba(245,170,0,' + (0.8 * k) + ')';
        ctx.shadowColor = 'rgba(255,200,40,0.9)'; ctx.shadowBlur = 16;
        ctx.lineWidth = (2 + 8 * k) * K; ctx.lineCap = 'round';
        ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
        ctx.strokeStyle = 'rgba(255,236,140,' + (0.95 * k) + ')'; ctx.shadowBlur = 0;
        ctx.lineWidth = (1 + 2.2 * k) * K;
        ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
      }

      // sprinkle cahaya
      for (let i = parts.length - 1; i >= 0; i--) {
        const q = parts[i]; q.life += dt;
        if (q.life > q.max) { parts.splice(i, 1); continue; }
        q.x += q.vx * dt; q.y += q.vy * dt; q.vy += 25 * dt; q.rot += dt * 2;
        const k = 1 - q.life / q.max;
        ctx.globalAlpha = k; ctx.fillStyle = q.c; ctx.shadowColor = '#FFB800'; ctx.shadowBlur = 12;
        if (q.star) sparkle(ctx, q.x, q.y, q.r * 1.8 * (0.6 + k * .6), q.rot);
        else { ctx.beginPath(); ctx.arc(q.x, q.y, q.r * k + .4, 0, 7); ctx.fill(); }
      }
      ctx.globalAlpha = 1; ctx.shadowBlur = 0;

      // tongkat: bintang di ujung jalur, gagang menjuntai di belakang gerakan
      if (ready && p < FLASH_AT + 0.04) {
        const sc = wandH / spr.height, dw = spr.width * sc, dh = wandH;
        const sx = STAR.x * dw, sy = STAR.y * dh;
        const axis = Math.atan2((HANDLE.y - STAR.y) * dh, (HANDLE.x - STAR.x) * dw);
        const thUp = Math.PI / 2 - axis, bl = blend(p);
        let thMo = Math.atan2(-vy, -vx) - axis + Math.sin(el / 120) * 0.12;
        let dth = ((thMo - thUp + Math.PI) % (Math.PI * 2) + Math.PI * 2) % (Math.PI * 2) - Math.PI;
        const theta = thUp + dth * bl;
        const fadeIn = Math.min(el / 500, 1), fadeOut = p > FLASH_AT ? Math.max(0, 1 - (p - FLASH_AT) / 0.04) : 1;
        const pop = ease(Math.min(el / 700, 1)), scl = (0.78 + 0.22 * (1 - ease(p))) * (0.55 + 0.45 * pop);
        ctx.save(); ctx.globalAlpha = fadeIn * fadeOut;
        ctx.translate(P.x, P.y); ctx.rotate(theta); ctx.scale(scl, scl);
        ctx.shadowColor = 'rgba(255,200,50,0.85)'; ctx.shadowBlur = 28;
        ctx.drawImage(spr, -sx, -sy, dw, dh);
        ctx.restore();
        // kilau di bintang
        const gl = ctx.createRadialGradient(P.x, P.y, 0, P.x, P.y, 44);
        gl.addColorStop(0, 'rgba(255,225,90,0.85)'); gl.addColorStop(1, 'rgba(255,196,0,0)');
        ctx.fillStyle = gl; ctx.beginPath(); ctx.arc(P.x, P.y, 44, 0, 7); ctx.fill();
      }

      // ledakan cahaya kuning di akhir lalu pindah halaman
      if (p >= FLASH_AT) {
        const f = (p - FLASH_AT) / (1 - FLASH_AT), r = Math.max(W, H) * 1.1 * ease(f);
        const fg = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(r, 1));
        fg.addColorStop(0, 'rgba(255,252,225,1)'); fg.addColorStop(0.55, 'rgba(255,236,150,' + (0.95 * Math.min(f * 2, 1)) + ')');
        fg.addColorStop(1, 'rgba(255,225,120,0)');
        ctx.fillStyle = fg; ctx.fillRect(0, 0, W, H);
        if (f > 0.55) { ctx.fillStyle = 'rgba(255,248,215,' + Math.min((f - 0.55) / 0.45, 1) + ')'; ctx.fillRect(0, 0, W, H); }
      }

      if (p >= 1) { done = true; go(); return; }
      requestAnimationFrame(frame);
    }
    const begin = () => { if (!began) { began = true; requestAnimationFrame(frame); } };
    let began = false;
    img.onload = () => { try { spr = prepare(img); ready = true; } catch (e) {} begin(); };
    img.onerror = () => {
      if (!usedFallback) { usedFallback = true; img = new Image(); img.onload = () => { try { spr = prepare(img); ready = true; } catch (e) {} begin(); }; img.onerror = begin; img.src = EMBEDDED; }
      else begin();
    };
    setTimeout(() => { if (!done) { done = true; go(); } }, INTRO + DUR + 1500); // pengaman
  }

  return { play };
})();
